export function buildRegionKey(level: RegionLevel, city?: string | null, district?: string | null, neighborhood?: string | null) {
  const cityPart = (city ?? '').trim()
  const districtPart = (district ?? '').trim() || '_'
  const neighborhoodPart = (neighborhood ?? '').trim() || '_'
  if (level === 'city') return cityPart ? `city:${cityPart}` : 'all'
  if (level === 'district') return cityPart ? `district:${cityPart}/${districtPart}` : 'all'
  if (level === 'neighborhood') return cityPart ? `neighborhood:${cityPart}/${districtPart}/${neighborhoodPart}` : 'all'
  return 'all'
}

export function regionPairKey(city?: string | null, district?: string | null) {
  return `${(city ?? '').trim()}||${(district ?? '').trim()}`
}

export function regionOptionsForLevel(level: RegionLevel, city?: string | null, district?: string | null) {
  if (level === 'city') return KOREA_CITIES
  if (level === 'district') return city ? (KOREA_DISTRICTS_BY_CITY[city] ?? []) : []
  if (level === 'neighborhood') return city ? (KOREA_NEIGHBORHOODS_BY_DISTRICT[regionPairKey(city, district)] ?? []) : []
  return []
}

export function regionLabelsFromKeys(keys: string[]) {
  return keys.map((key) => KOREA_REGION_LOOKUP[key]?.fullLabel ?? key)
}

export function regionSummaryFromKeys(keys: string[]) {
  const labels = regionLabelsFromKeys(keys)
  if (labels.length === 0) return '전체지역'
  if (labels.length === 1) return labels[0]
  return `${labels[0]} 외 ${labels.length - 1}`
}

export function parseRegionTokens(raw: string) {
  return raw
    .split(/[\n,;]+/)
    .map((item) => item.trim())
    .filter(Boolean)
}

export function regionKeysFromTokens(tokens: string[]) {
  const matched = new Set<string>()
  for (const token of tokens) {
    if (KOREA_REGION_LOOKUP[token]) {
      matched.add(token)
      continue
    }
    const found = Object.values(KOREA_REGION_LOOKUP).find((option) => option.fullLabel === token || option.label === token)
    if (found) matched.add(found.key)
  }
  return Array.from(matched)
}
